st={}
net.blocks[2].act.register_forward_hook(lambda m,i,o: st.__setitem__('act',o))
net.inp.register_forward_hook(lambda m,i,o: st.__setitem__('x',i[0]))
def hk(m,i,o):
    if st.get('s',0)==0: return o
    k=st['k']
    if not(st['lo']<=k<st['hi']): return o
    f=((st['act']@w+b)>st['thr']).float()[:,None]
    x=st['x']; d=st['s']*torch.stack([-x[:,1],x[:,0]],1)
    return o+f*d
net.out.register_forward_hook(hk)
def dec(xi,c):
    x=xi.clone()
    with torch.no_grad():
        for k in range(20):
            st['k']=k; t=torch.full((x.shape[0],),1-k/20)
