import numpy as np, torch, model
net=model.load()
dw=torch.tensor(np.load('contrast_c4_blocks.2_k6.npy')); db=-14.6696
torch.manual_seed(1); N=4096
xs=torch.randn(N,2); cs=torch.rand(N); C=cs.numpy()
J=torch.tensor([[0.,-1.],[1.,0.]])
def dec(al=0,thr=0,klo=0,khi=7):
    x=xs.clone(); fires=[]
    for k in range(20):
        t=torch.full((N,),1-k/20)
        with torch.no_grad(): v,A=net.velocity(x,t,cs,('blocks.2',),count=False)
        s=A['blocks.2']@dw+db
        if k<7: fires.append(s>0)
        if al and klo<=k<khi:
            v=v+(s>thr).float()[:,None]*(x@(-al*J).T)
        x=x-v/20
    return x.numpy(), torch.stack(fires).numpy()
a0,f0=dec(); frac=f0.mean(0)
lab=np.zeros(N,bool)
for lo in np.arange(0,1,0.05):
    m=(C>=lo)&(C<lo+0.05); ctr=np.median(a0[m&(frac>=0.5)],0)
    lab|=m&(np.linalg.norm(a0-ctr,axis=1)<1.0)
P=torch.tensor(np.c_[a0,C*3]); Ptr=P[torch.tensor(lab)]; Pok=P[torch.tensor(~lab)]
def ev(a):
    Q=torch.tensor(np.c_[a,C*3])
    dtr=torch.cdist(Q,Ptr).min(1).values.numpy(); dok=torch.cdist(Q,Pok).min(1).values.numpy()
    intr=(dtr<dok)&(dtr<0.4)
    mv=np.linalg.norm(a-a0,axis=1)>0.3
    return intr.mean(), mv[~lab].mean(), mv.mean()
for al in [3,6]:
  for thr in [0,2,4,6,8]:
    for kr in [(0,7),(0,4),(3,7)]:
      a,_=dec(al,thr,*kr); print(al,thr,kr,np.round(ev(a),3))

